	fmt.Fprintln(os.Stderr, "    delete-apiv1-workspaces-by-slug-projects-by-project-id-archive: Restore an archived project to active status, making it available in regular workflows.")
	fmt.Fprintln(os.Stderr, "    post-apiv1-workspaces-by-slug-projects-by-project-id-archive: Move a project to archived status, hiding it from active project lists.")
	fmt.Fprintln(os.Stderr, "    get-apiv1-workspaces-by-slug-projects-by-project-id-summary: Get project summary\n\t\n\tGet the summary of a project")
	fmt.Fprintln(os.Stderr, "    post-api-workspaces-by-slug-projects: This enables timezone conversion according\n\tto the user set timezone")
	fmt.Fprintln(os.Stderr, "    delete-api-workspaces-by-slug-projects-by-pk: This enables timezone conversion according\n\tto the user set timezone")
